package com.classeschedule.widget;
import android.app.Activity;import android.appwidget.AppWidgetManager;import android.content.ComponentName;import android.content.Intent;import android.os.Bundle;import android.widget.Button;import android.widget.TextView;
public class MainActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);Button x=findViewById(R.id.testButton);TextView s=findViewById(R.id.status);x.setOnClickListener(v->{getSharedPreferences("schedule",MODE_PRIVATE).edit().putString("subject","Mathematics").putString("time","7:30 AM – 8:30 AM").putString("room","Room 101").putString("teacher","Teacher Name").apply();sendBroadcast(new Intent(this,ScheduleWidgetProvider.class));s.setText("Sample class saved. Add the widget to your home screen.");});}}